class RequestHandler(BaseHTTPRequestHandler):
    def _send_json(self, status_code, data):
        self.send_response(status_code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(data).encode("utf-8"))

    def _send_html(self, status_code, html):
        self.send_response(status_code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.end_headers()
        self.wfile.write(html.encode("utf-8"))

    def do_GET(self):
        if self.path == "/health":
            self._send_json(200, {"status": "ok"})
        elif self.path == "/" or self.path.startswith("/?"):
            self._send_html(200, INDEX_HTML)
        elif self.path == "/favicon.ico":
            self.send_response(204)
            self.end_headers()
        else:
            self._send_json(404, {"error": "Not Found"})

    def do_HEAD(self):
        if self.path == "/health":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
        elif self.path == "/" or self.path.startswith("/?"):
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
        else:
            self.send_response(404)
            self.send_header("Content-Type", "application/json")
            self.end_headers()

    def do_POST(self):
        if self.path != "/api/action":
            self._send_json(404, {"error": "Not Found"})
            return

        try:
            content_length = int(self.headers.get("Content-Length", 0))
        except (TypeError, ValueError):
            self._send_json(400, {"error": "Invalid Content-Length"})
            return
        if content_length < 0:
            self._send_json(400, {"error": "Invalid Content-Length"})
            return
        post_data = self.rfile.read(content_length)

        try:
            request = json.loads(post_data.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._send_json(400, {"error": "Invalid JSON"})
            return

        if not isinstance(request, dict):
            self._send_json(400, {"error": "Request body must be a JSON object"})
            return

        data_dir = self.server.data_dir

        try:
            response = handle(data_dir, request)
            self._send_json(200, response)
        except ValueError as e:
            self._send_json(400, {"error": str(e)})
        except Exception as e:
            self._send_json(500, {"error": "Internal Server Error: %s" % str(e)})

    def log_message(self, format, *args):
        pass


class ThreadedHTTPServer(HTTPServer):
    allow_reuse_address = True
    daemon_threads = True

    def __init__(self, host, port, data_dir):
        super().__init__((host, port), RequestHandler)
        self.data_dir = data_dir

    def serve_forever_threaded(self):
        thread = threading.Thread(target=self.serve_forever)
        thread.daemon = True
        thread.start()
        return thread


def main():
    if len(sys.argv) < 2:
        print("Usage: python early_main.py --serve --port PORT --data DIR")
        sys.exit(0)

    args = sys.argv[1:]
    if "--serve" not in args:
        print("Usage: python early_main.py --serve --port PORT --data DIR")
        sys.exit(0)

    port = 8080
    data_dir = "./data"

    try:
        if "--port" in args:
            idx = args.index("--port")
            port = int(args[idx + 1])
        if "--data" in args:
            idx = args.index("--data")
            data_dir = args[idx + 1]
    except (IndexError, ValueError):
        print("Invalid arguments")
        sys.exit(1)

    os.makedirs(data_dir, exist_ok=True)

    server = ThreadedHTTPServer("localhost", port, data_dir)
    print("Serving on localhost:%d with data dir %s" % (port, data_dir))
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

"""Claim Ledger module (M3).

Provides persistent, isolated claim management with deterministic validity computation based on evidence status and content matching.
Reuses M1 project isolation and persistence, and M2 evidence/signal structures.
"""

import json
import os
import uuid

MILESTONE_ID = "M3"

_PROJECTS_FILENAME = "projects.json"
_EVIDENCE_FILENAME = "evidence.json"
_CLAIMS_FILENAME = "claims.json"


def _path(data_dir, filename):
    return os.path.join(data_dir, filename)


def _load_list(data_dir, filename):
    path = _path(data_dir, filename)
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    if not content.strip():
        return []
    data = json.loads(content)
    if not isinstance(data, list):
        return []
    return data


def _save_list(data_dir, filename, items):
    os.makedirs(data_dir, exist_ok=True)
    path = _path(data_dir, filename)
    tmp_path = path + ".tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False)
    os.replace(tmp_path, path)


def _load_projects(data_dir):
    return _load_list(data_dir, _PROJECTS_FILENAME)


def _require_project(data_dir, project_id):
    if not isinstance(project_id, str) or not project_id:
        raise ValueError("project_id must be a non-empty string")
    for record in _load_projects(data_dir):
        if record.get("id") == project_id:
            return record
    raise ValueError("project not found: %s" % project_id)


def _find_evidence(evidence, project_id, evidence_id):
    if not isinstance(evidence_id, str) or not evidence_id:
        raise ValueError("evidence_id must be a non-empty string")
    for record in evidence:
        if record.get("id") == evidence_id:
            if record.get("project_id") != project_id:
                raise ValueError("evidence not found: %s" % evidence_id)
            return record
    raise ValueError("evidence not found: %s" % evidence_id)


def _compute_status(claim_text, cited_evidence_records):
    """
    Compute status based on spec:
    - SUPPORTED: If the claim text is an exact substring of the current (non-SUPERSEDED) text content of at least one cited evidence file.
    - UNSUPPORTED: If no evidence is cited, or if the claim text is not found in any current cited evidence.
    - STALE: If all cited evidence records are SUPERSEDED.
    - CONFLICT: Only set via explicit conflict operation; create never sets this initially unless logic dictates otherwise.
    """
    if not cited_evidence_records:
        return "UNSUPPORTED"

    # Check if all cited evidence are SUPERSEDED
    all_superseded = True
    has_current_support = False

    for ev in cited_evidence_records:
        if ev["status"] != "SUPERSEDED":
            all_superseded = False
            # Check if claim text is substring of any file in this evidence
            for file_info in ev.get("files", []):
                if claim_text in file_info.get("text", ""):
                    has_current_support = True
                    break
        if has_current_support:
            break

    if all_superseded:
        return "STALE"
    
    if has_current_support:
        return "SUPPORTED"
    
    return "UNSUPPORTED"


def _public_claim(record):
    return {
        "id": record["id"],
        "project_id": record["project_id"],
        "text": record["text"],
        "evidence_ids": record["evidence_ids"],
        "status": record["status"],
        "reason": record.get("reason")
    }


def handle(data_dir, request):
    if not isinstance(data_dir, str) or not data_dir:
        raise ValueError("data_dir must be a non-empty string")
    if not isinstance(request, dict):
        raise ValueError("request must be a dict")

    op = request.get("op")
    if not isinstance(op, str) or not op:
        raise ValueError("request must contain a non-empty 'op' string")

    if op == "claim.create":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        
        text = request.get("text")
        if not isinstance(text, str) or not text.strip():
            raise ValueError("text must be a non-empty string")
            
        evidence_ids = request.get("evidence_ids")
        if not isinstance(evidence_ids, list):
             raise ValueError("evidence_ids must be a list")
             
        evidence = _load_list(data_dir, _EVIDENCE_FILENAME)
        cited_evidence_records = []
        for eid in evidence_ids:
            rec = _find_evidence(evidence, project_id, eid)
            cited_evidence_records.append(rec)
            
        status = _compute_status(text, cited_evidence_records)
        
        claims = _load_list(data_dir, _CLAIMS_FILENAME)
        record = {
            "id": uuid.uuid4().hex,
            "project_id": project_id,
            "text": text,
            "evidence_ids": evidence_ids,
            "status": status,
        }
        claims.append(record)
        _save_list(data_dir, _CLAIMS_FILENAME, claims)
        return _public_claim(record)

    if op == "claim.get":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        claim_id = request.get("claim_id")
        if not isinstance(claim_id, str) or not claim_id:
            raise ValueError("claim_id must be a non-empty string")
            
        claims = _load_list(data_dir, _CLAIMS_FILENAME)
        target_claim = None
        for c in claims:
            if c["id"] == claim_id:
                if c["project_id"] != project_id:
                    raise ValueError("claim not found: %s" % claim_id)
                target_claim = c
                break
        
        if not target_claim:
            raise ValueError("claim not found: %s" % claim_id)
            
        # Recompute status based on latest evidence state
        # Note: Spec says "claim.conflict marks... This overrides the computed status until the claim is potentially re-evaluated or modified"
        # But also "claim.get recomputes the current validity status..."
        # And "CONFLICT: Only set via explicit conflict operation..."
        # Usually, if a claim is explicitly marked CONFLICT, get might keep it CONFLICT or recompute? 
        # The spec says: "claim.conflict marks a specific claim as CONFLICT with a persistent reason. This overrides the computed status until the claim is potentially re-evaluated or modified (though modification isn't supported here, so it stays CONFLICT)."
        # So if status is already CONFLICT, we should probably keep it CONFLICT unless there's a way to clear it? 
        # However, standard interpretation of "recomputes" usually implies checking evidence again. 
        # BUT, the edge behavior says: "CONFLICT: Only set via explicit conflict operation; create never sets this initially..."
        # And: "claim.conflict ... overrides the computed status ... so it stays CONFLICT".
        # This implies that once CONFLICT, it remains CONFLICT even on get, because there is no "clear conflict" operation.
        
        if target_claim["status"] == "CONFLICT":
            return _public_claim(target_claim)
            
        evidence = _load_list(data_dir, _EVIDENCE_FILENAME)
        cited_evidence_records = []
        for eid in target_claim["evidence_ids"]:
            try:
                rec = _find_evidence(evidence, project_id, eid)
                cited_evidence_records.append(rec)
            except ValueError:
                # Evidence deleted? Treat as missing/unsupported?
                # Spec doesn't explicitly say what happens if evidence disappears.
                # Safest is to treat as not supporting the claim.
                pass
                
        new_status = _compute_status(target_claim["text"], cited_evidence_records)
        target_claim["status"] = new_status
        _save_list(data_dir, _CLAIMS_FILENAME, claims)
        
        return _public_claim(target_claim)

    if op == "claim.list":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        claims = _load_list(data_dir, _CLAIMS_FILENAME)
        evidence = _load_list(data_dir, _EVIDENCE_FILENAME)
        
        items = []
        for c in claims:
            if c["project_id"] != project_id:
                continue
                
            # Recompute status for list as well? 
            # Spec: "claim.list returns {items: [...]} containing all claims for the project with their currently computed statuses."
            # Yes, compute status.
            
            if c["status"] == "CONFLICT":
                items.append(_public_claim(c))
                continue
                
            cited_evidence_records = []
            for eid in c["evidence_ids"]:
                try:
                    rec = _find_evidence(evidence, project_id, eid)
                    cited_evidence_records.append(rec)
                except ValueError:
                    pass
                    
            new_status = _compute_status(c["text"], cited_evidence_records)
            c["status"] = new_status
            items.append(_public_claim(c))
            
        _save_list(data_dir, _CLAIMS_FILENAME, claims)
        return {"items": items}

    if op == "claim.conflict":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        claim_id = request.get("claim_id")
        if not isinstance(claim_id, str) or not claim_id:
            raise ValueError("claim_id must be a non-empty string")
            
        reason = request.get("reason")
        if not isinstance(reason, str) or not reason.strip():
            raise ValueError("reason must be a non-empty string")
            
        claims = _load_list(data_dir, _CLAIMS_FILENAME)
        target_claim = None
        for c in claims:
            if c["id"] == claim_id:
                if c["project_id"] != project_id:
                    raise ValueError("claim not found: %s" % claim_id)
                target_claim = c
                break
                
        if not target_claim:
            raise ValueError("claim not found: %s" % claim_id)
            
        target_claim["status"] = "CONFLICT"
        target_claim["reason"] = reason
        _save_list(data_dir, _CLAIMS_FILENAME, claims)
        
        return _public_claim(target_claim)

    raise ValueError("unknown operation: %s" % op)

"""Project Workspace module (M1).

Provides persistent, isolated project management via handle(data_dir, request).
"""

import json
import os
import uuid

MILESTONE_ID = "M1"

_STORE_FILENAME = "projects.json"


def _store_path(data_dir):
    return os.path.join(data_dir, _STORE_FILENAME)


def _load(data_dir):
    path = _store_path(data_dir)
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    if not content.strip():
        return []
    data = json.loads(content)
    if not isinstance(data, list):
        return []
    return data


def _save(data_dir, projects):
    os.makedirs(data_dir, exist_ok=True)
    path = _store_path(data_dir)
    tmp_path = path + ".tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(projects, f, ensure_ascii=False)
    os.replace(tmp_path, path)


def handle(data_dir, request):
    if not isinstance(data_dir, str) or not data_dir:
        raise ValueError("data_dir must be a non-empty string")
    if not isinstance(request, dict):
        raise ValueError("request must be a dict")

    op = request.get("op")
    if not isinstance(op, str) or not op:
        raise ValueError("request must contain a non-empty 'op' string")

    if op == "project.create":
        name = request.get("name")
        if not isinstance(name, str) or not name.strip():
            raise ValueError("project name must be a non-empty string")
        projects = _load(data_dir)
        project_id = uuid.uuid4().hex
        record = {"id": project_id, "name": name}
        projects.append(record)
        _save(data_dir, projects)
        return {"id": project_id, "name": name}

    if op == "project.get":
        project_id = request.get("project_id")
        if not isinstance(project_id, str) or not project_id:
            raise ValueError("project_id must be a non-empty string")
        projects = _load(data_dir)
        for record in projects:
            if record.get("id") == project_id:
                return {"id": record["id"], "name": record["name"]}
        raise ValueError("project not found: %s" % project_id)

    if op == "project.list":
        projects = _load(data_dir)
        items = [{"id": r["id"], "name": r["name"]} for r in projects]
        return {"items": items}

    raise ValueError("unknown operation: %s" % op)

"""Milestone M6: Approval.

Provides persistent, isolated approval management (review, approve, status)
for content items, enforcing strict revision binding, claim validity, and
media presence checks. Reuses M1 project isolation, M3 claim structures,
and M5 content structures.
"""

import json
import os

MILESTONE_ID = "M6"

_PROJECTS_FILENAME = "projects.json"
_CLAIMS_FILENAME = "claims.json"
_CONTENT_FILENAME = "content.json"


def _path(data_dir, filename):
    return os.path.join(data_dir, filename)


def _load_list(data_dir, filename):
    path = _path(data_dir, filename)
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    if not content.strip():
        return []
    data = json.loads(content)
    if not isinstance(data, list):
        return []
    return data


def _save_list(data_dir, filename, items):
    os.makedirs(data_dir, exist_ok=True)
    path = _path(data_dir, filename)
    tmp_path = path + ".tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False)
    os.replace(tmp_path, path)


def _require_project(data_dir, project_id):
    if not isinstance(project_id, str) or not project_id:
        raise ValueError("project_id must be a non-empty string")
    for record in _load_list(data_dir, _PROJECTS_FILENAME):
        if record.get("id") == project_id:
            return record
    raise ValueError("project not found: %s" % project_id)


def _find_content(content_items, project_id, content_id):
    if not isinstance(content_id, str) or not content_id:
        raise ValueError("content_id must be a non-empty string")
    for record in content_items:
        if record.get("id") == content_id:
            if record.get("project_id") != project_id:
                raise ValueError("content not found: %s" % content_id)
            return record
    raise ValueError("content not found: %s" % content_id)


def _compute_claim_status(claim_text, cited_evidence_records):
    if not cited_evidence_records:
        return "UNSUPPORTED"
    all_superseded = True
    has_current_support = False
    for ev in cited_evidence_records:
        if ev.get("status") != "SUPERSEDED":
            all_superseded = False
            for file_info in ev.get("files", []):
                if claim_text in file_info.get("text", ""):
                    has_current_support = True
                    break
        if has_current_support:
            break
    if all_superseded:
        return "STALE"
    if has_current_support:
        return "SUPPORTED"
    return "UNSUPPORTED"


def _current_claim_status(data_dir, project_id, claim_record):
    if claim_record.get("status") == "CONFLICT":
        return "CONFLICT"
    evidence = _load_list(data_dir, "evidence.json")
    cited = []
    for eid in claim_record.get("evidence_ids", []):
        for ev in evidence:
            if ev.get("id") == eid and ev.get("project_id") == project_id:
                cited.append(ev)
                break
    return _compute_claim_status(claim_record.get("text", ""), cited)


def _validate_claims_supported(data_dir, project_id, claim_ids):
    claims = _load_list(data_dir, _CLAIMS_FILENAME)
    for cid in claim_ids:
        found = None
        for c in claims:
            if c.get("id") == cid:
                if c.get("project_id") != project_id:
                    raise ValueError("claim not found: %s" % cid)
                found = c
                break
        if found is None:
            raise ValueError("claim not found: %s" % cid)
        status = _current_claim_status(data_dir, project_id, found)
        if status != "SUPPORTED":
            raise ValueError("claim not supported: %s (%s)" % (cid, status))


def _validate_media_present(media_ids):
    if not isinstance(media_ids, list):
        raise ValueError("media_ids must be a list")
    for mid in media_ids:
        if not isinstance(mid, str) or not mid:
            raise ValueError("media_ids must contain non-empty strings")


def _result(content_id, revision, status):
    return {"content_id": content_id, "revision": revision, "status": status}


def handle(data_dir, request):
    if not isinstance(data_dir, str) or not data_dir:
        raise ValueError("data_dir must be a non-empty string")
    if not isinstance(request, dict):
        raise ValueError("request must be a dict")

    op = request.get("op")
    if not isinstance(op, str) or not op:
        raise ValueError("request must contain a non-empty 'op' string")

    if op == "approval.review":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        content_id = request.get("content_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        record = _find_content(content_items, project_id, content_id)
        record["status"] = "REVIEW"
        _save_list(data_dir, _CONTENT_FILENAME, content_items)
        return _result(record["id"], record["revision"], "REVIEW")

    if op == "approval.approve":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        content_id = request.get("content_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        record = _find_content(content_items, project_id, content_id)
        if record.get("status") != "REVIEW":
            raise ValueError("content not reviewed: %s" % content_id)
        _validate_claims_supported(data_dir, project_id, record.get("claim_ids", []))
        _validate_media_present(record.get("media_ids", []))
        record["status"] = "APPROVED"
        _save_list(data_dir, _CONTENT_FILENAME, content_items)
        return _result(record["id"], record["revision"], "APPROVED")

    if op == "approval.status":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        content_id = request.get("content_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        record = _find_content(content_items, project_id, content_id)
        return _result(record["id"], record["revision"], record.get("status", "DRAFT"))

    raise ValueError("unknown operation: %s" % op)

"""Campaign CRUD module (M4).



Provides persistent, isolated campaign management with validation and history tracking.

Reuses M1 project isolation and persistence patterns.

"""



import json

import os

import uuid



MILESTONE_ID = "M4"



_PROJECTS_FILENAME = "projects.json"

_CAMPAIGNS_FILENAME = "campaigns.json"





def _path(data_dir, filename):

    return os.path.join(data_dir, filename)





def _load_list(data_dir, filename):

    path = _path(data_dir, filename)

    if not os.path.exists(path):

        return []

    with open(path, "r", encoding="utf-8") as f:

        content = f.read()

    if not content.strip():

        return []

    data = json.loads(content)

    if not isinstance(data, list):

        return []

    return data





def _save_list(data_dir, filename, items):

    os.makedirs(data_dir, exist_ok=True)

    path = _path(data_dir, filename)

    tmp_path = path + ".tmp"

    with open(tmp_path, "w", encoding="utf-8") as f:

        json.dump(items, f, ensure_ascii=False)

    os.replace(tmp_path, path)





def _load_projects(data_dir):

    return _load_list(data_dir, _PROJECTS_FILENAME)





def _require_project(data_dir, project_id):

    if not isinstance(project_id, str) or not project_id:

        raise ValueError("project_id must be a non-empty string")

    for record in _load_projects(data_dir):

        if record.get("id") == project_id:

            return record

    raise ValueError("project not found: %s" % project_id)





def _validate_channels(channels):

    if not isinstance(channels, list):

        raise ValueError("channels must be a list")

    if len(channels) == 0:

        raise ValueError("channels must not be empty")

    seen = set()

    for c in channels:

        if not isinstance(c, str):

            raise ValueError("channels must contain only strings")

        if not c.strip():

            raise ValueError("channels must not contain empty strings")

        if c in seen:

            raise ValueError("channels must be unique")

        seen.add(c)





def _find_campaign(campaigns, project_id, campaign_id):

    if not isinstance(campaign_id, str) or not campaign_id:

        raise ValueError("campaign_id must be a non-empty string")

    for record in campaigns:

        if record.get("id") == campaign_id:

            if record.get("project_id") != project_id:

                raise ValueError("campaign not found: %s" % campaign_id)

            return record

    raise ValueError("campaign not found: %s" % campaign_id)





def _public_campaign(record):

    return {

        "id": record["id"],

        "project_id": record["project_id"],

        "name": record["name"],

        "audience": record["audience"],

        "channels": record["channels"],

        "status": record["status"],

        "history": record["history"]

    }





def handle(data_dir, request):

    if not isinstance(data_dir, str) or not data_dir:

        raise ValueError("data_dir must be a non-empty string")

    if not isinstance(request, dict):

        raise ValueError("request must be a dict")



    op = request.get("op")

    if not isinstance(op, str) or not op:

        raise ValueError("request must contain a non-empty 'op' string")



    if op == "campaign.create":

        project_id = request.get("project_id")

        _require_project(data_dir, project_id)



        name = request.get("name")

        if not isinstance(name, str) or not name.strip():

            raise ValueError("name must be a non-empty string")



        audience = request.get("audience")

        if not isinstance(audience, str) or not audience.strip():

            raise ValueError("audience must be a non-empty string")



        channels = request.get("channels")

        _validate_channels(channels)



        campaigns = _load_list(data_dir, _CAMPAIGNS_FILENAME)

        record = {

            "id": uuid.uuid4().hex,

            "project_id": project_id,

            "name": name,

            "audience": audience,

            "channels": channels,

            "status": "ACTIVE",

            "history": []

        }

        campaigns.append(record)

        _save_list(data_dir, _CAMPAIGNS_FILENAME, campaigns)

        return _public_campaign(record)



    if op == "campaign.get":

        project_id = request.get("project_id")

        _require_project(data_dir, project_id)

        campaign_id = request.get("campaign_id")

        

        campaigns = _load_list(data_dir, _CAMPAIGNS_FILENAME)

        target_campaign = _find_campaign(campaigns, project_id, campaign_id)

        

        return _public_campaign(target_campaign)



    if op == "campaign.update":

        project_id = request.get("project_id")

        _require_project(data_dir, project_id)

        campaign_id = request.get("campaign_id")

        

        campaigns = _load_list(data_dir, _CAMPAIGNS_FILENAME)

        target_campaign = _find_campaign(campaigns, project_id, campaign_id)

        

        if target_campaign["status"] == "ARCHIVED":

            raise ValueError("cannot update archived campaign")

            

        # Validate new inputs

        name = request.get("name")

        if not isinstance(name, str) or not name.strip():

            raise ValueError("name must be a non-empty string")

            

        audience = request.get("audience")

        if not isinstance(audience, str) or not audience.strip():

            raise ValueError("audience must be a non-empty string")

            

        channels = request.get("channels")

        _validate_channels(channels)

        

        # Append previous state to history

        prev_state = {

            "id": target_campaign["id"],

            "project_id": target_campaign["project_id"],

            "name": target_campaign["name"],

            "audience": target_campaign["audience"],

            "channels": list(target_campaign["channels"]),

            "status": target_campaign["status"]

        }

        if not isinstance(target_campaign.get("history"), list):

            target_campaign["history"] = []

        target_campaign["history"].append(prev_state)

        

        # Update fields (preserving id and project_id)

        target_campaign["name"] = name

        target_campaign["audience"] = audience

        target_campaign["channels"] = channels

        

        _save_list(data_dir, _CAMPAIGNS_FILENAME, campaigns)

        return _public_campaign(target_campaign)



    if op == "campaign.archive":

        project_id = request.get("project_id")

        _require_project(data_dir, project_id)

        campaign_id = request.get("campaign_id")

        

        campaigns = _load_list(data_dir, _CAMPAIGNS_FILENAME)

        target_campaign = _find_campaign(campaigns, project_id, campaign_id)

        

        target_campaign["status"] = "ARCHIVED"

        

        _save_list(data_dir, _CAMPAIGNS_FILENAME, campaigns)

        return _public_campaign(target_campaign)



    if op == "campaign.list":

        project_id = request.get("project_id")

        _require_project(data_dir, project_id)

        

        campaigns = _load_list(data_dir, _CAMPAIGNS_FILENAME)

        items = [_public_campaign(r) for r in campaigns if r.get("project_id") == project_id]

        return {"items": items}



    raise ValueError("unknown operation: %s" % op)

"""Content Studio module (M5).

Provides persistent, isolated content management with revision history,
validation against project/campaign/claim constraints, and support for
create, get, list, edit, revisions, and compare operations.
Reuses M1 project isolation, M3 claim structures, and M4 campaign structures.
"""

import json
import os
import uuid

MILESTONE_ID = "M5"

_PROJECTS_FILENAME = "projects.json"
_CAMPAIGNS_FILENAME = "campaigns.json"
_CLAIMS_FILENAME = "claims.json"
_CONTENT_FILENAME = "content.json"


def _path(data_dir, filename):
    return os.path.join(data_dir, filename)


def _load_list(data_dir, filename):
    path = _path(data_dir, filename)
    if not os.path.exists(path):
        return []
    with open(path, "r", encoding="utf-8") as f:
        content = f.read()
    if not content.strip():
        return []
    data = json.loads(content)
    if not isinstance(data, list):
        return []
    return data


def _save_list(data_dir, filename, items):
    os.makedirs(data_dir, exist_ok=True)
    path = _path(data_dir, filename)
    tmp_path = path + ".tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False)
    os.replace(tmp_path, path)


def _require_project(data_dir, project_id):
    if not isinstance(project_id, str) or not project_id:
        raise ValueError("project_id must be a non-empty string")
    for record in _load_list(data_dir, _PROJECTS_FILENAME):
        if record.get("id") == project_id:
            return record
    raise ValueError("project not found: %s" % project_id)


def _find_campaign(data_dir, project_id, campaign_id):
    if not isinstance(campaign_id, str) or not campaign_id:
        raise ValueError("campaign_id must be a non-empty string")
    for record in _load_list(data_dir, _CAMPAIGNS_FILENAME):
        if record.get("id") == campaign_id:
            if record.get("project_id") != project_id:
                raise ValueError("campaign not found: %s" % campaign_id)
            return record
    raise ValueError("campaign not found: %s" % campaign_id)


def _validate_claim_ids(data_dir, project_id, claim_ids):
    if not isinstance(claim_ids, list):
        raise ValueError("claim_ids must be a list")
    claims = _load_list(data_dir, _CLAIMS_FILENAME)
    for cid in claim_ids:
        if not isinstance(cid, str) or not cid:
            raise ValueError("claim_ids must contain non-empty strings")
        found = False
        for c in claims:
            if c.get("id") == cid:
                if c.get("project_id") != project_id:
                    raise ValueError("claim not found: %s" % cid)
                found = True
                break
        if not found:
            raise ValueError("claim not found: %s" % cid)


def _validate_media_ids(media_ids):
    if not isinstance(media_ids, list):
        raise ValueError("media_ids must be a list")
    for mid in media_ids:
        if not isinstance(mid, str) or not mid:
            raise ValueError("media_ids must contain non-empty strings")


def _validate_text(text):
    if not isinstance(text, str) or not text.strip():
        raise ValueError("text must be a non-empty string")


def _validate_channel(campaign, channel):
    if not isinstance(channel, str) or not channel:
        raise ValueError("channel must be a non-empty string")
    if channel not in campaign.get("channels", []):
        raise ValueError("channel not permitted: %s" % channel)


def _find_content(content_items, project_id, content_id):
    if not isinstance(content_id, str) or not content_id:
        raise ValueError("content_id must be a non-empty string")
    for record in content_items:
        if record.get("id") == content_id:
            if record.get("project_id") != project_id:
                raise ValueError("content not found: %s" % content_id)
            return record
    raise ValueError("content not found: %s" % content_id)


def _public_content(record):
    return {
        "id": record["id"],
        "project_id": record["project_id"],
        "campaign_id": record["campaign_id"],
        "channel": record["channel"],
        "text": record["text"],
        "claim_ids": list(record["claim_ids"]),
        "media_ids": list(record["media_ids"]),
        "revision": record["revision"],
        "status": record["status"],
    }


def _public_revision(rev):
    return {
        "id": rev["id"],
        "project_id": rev["project_id"],
        "campaign_id": rev["campaign_id"],
        "channel": rev["channel"],
        "text": rev["text"],
        "claim_ids": list(rev["claim_ids"]),
        "media_ids": list(rev["media_ids"]),
        "revision": rev["revision"],
        "status": rev["status"],
    }


def handle(data_dir, request):
    if not isinstance(data_dir, str) or not data_dir:
        raise ValueError("data_dir must be a non-empty string")
    if not isinstance(request, dict):
        raise ValueError("request must be a dict")

    op = request.get("op")
    if not isinstance(op, str) or not op:
        raise ValueError("request must contain a non-empty 'op' string")

    if op == "content.create":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)

        campaign_id = request.get("campaign_id")
        campaign = _find_campaign(data_dir, project_id, campaign_id)
        if campaign.get("status") != "ACTIVE":
            raise ValueError("campaign is not active: %s" % campaign_id)

        channel = request.get("channel")
        _validate_channel(campaign, channel)

        text = request.get("text")
        _validate_text(text)

        claim_ids = request.get("claim_ids")
        if claim_ids is None:
            claim_ids = []
        _validate_claim_ids(data_dir, project_id, claim_ids)

        media_ids = request.get("media_ids")
        if media_ids is None:
            media_ids = []
        _validate_media_ids(media_ids)

        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        content_id = uuid.uuid4().hex
        revision_record = {
            "id": content_id,
            "project_id": project_id,
            "campaign_id": campaign_id,
            "channel": channel,
            "text": text,
            "claim_ids": list(claim_ids),
            "media_ids": list(media_ids),
            "revision": 1,
            "status": "DRAFT",
        }
        record = {
            "id": content_id,
            "project_id": project_id,
            "campaign_id": campaign_id,
            "channel": channel,
            "text": text,
            "claim_ids": list(claim_ids),
            "media_ids": list(media_ids),
            "revision": 1,
            "status": "DRAFT",
            "revisions": [revision_record],
        }
        content_items.append(record)
        _save_list(data_dir, _CONTENT_FILENAME, content_items)
        return _public_content(record)

    if op == "content.get":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        content_id = request.get("content_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        record = _find_content(content_items, project_id, content_id)
        return _public_content(record)

    if op == "content.revisions":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        content_id = request.get("content_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        record = _find_content(content_items, project_id, content_id)
        items = [_public_revision(r) for r in record.get("revisions", [])]
        return {"items": items}

    if op == "content.edit":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        content_id = request.get("content_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        record = _find_content(content_items, project_id, content_id)

        campaign_id = record["campaign_id"]
        campaign = _find_campaign(data_dir, project_id, campaign_id)
        if campaign.get("status") != "ACTIVE":
            raise ValueError("campaign is not active: %s" % campaign_id)

        channel = record["channel"]
        _validate_channel(campaign, channel)

        text = request.get("text")
        _validate_text(text)

        if "claim_ids" in request and request.get("claim_ids") is not None:
            claim_ids = request.get("claim_ids")
            _validate_claim_ids(data_dir, project_id, claim_ids)
        else:
            claim_ids = list(record["claim_ids"])

        if "media_ids" in request and request.get("media_ids") is not None:
            media_ids = request.get("media_ids")
            _validate_media_ids(media_ids)
        else:
            media_ids = list(record["media_ids"])

        new_revision_number = record["revision"] + 1
        revision_record = {
            "id": content_id,
            "project_id": project_id,
            "campaign_id": campaign_id,
            "channel": channel,
            "text": text,
            "claim_ids": list(claim_ids),
            "media_ids": list(media_ids),
            "revision": new_revision_number,
            "status": "DRAFT",
        }

        record["text"] = text
        record["claim_ids"] = list(claim_ids)
        record["media_ids"] = list(media_ids)
        record["revision"] = new_revision_number
        record["status"] = "DRAFT"
        if not isinstance(record.get("revisions"), list):
            record["revisions"] = []
        record["revisions"].append(revision_record)

        _save_list(data_dir, _CONTENT_FILENAME, content_items)
        return _public_content(record)

    if op == "content.compare":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        content_id = request.get("content_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        record = _find_content(content_items, project_id, content_id)

        from_revision = request.get("from_revision")
        to_revision = request.get("to_revision")
        if not isinstance(from_revision, int) or isinstance(from_revision, bool):
            raise ValueError("from_revision must be an integer")
        if not isinstance(to_revision, int) or isinstance(to_revision, bool):
            raise ValueError("to_revision must be an integer")

        revisions = record.get("revisions", [])
        before = None
        after = None
        for r in revisions:
            if r.get("revision") == from_revision:
                before = r
            if r.get("revision") == to_revision:
                after = r
        if before is None:
            raise ValueError("revision not found: %s" % from_revision)
        if after is None:
            raise ValueError("revision not found: %s" % to_revision)

        return {"before": _public_revision(before), "after": _public_revision(after)}

    if op == "content.list":
        project_id = request.get("project_id")
        _require_project(data_dir, project_id)
        campaign_id = request.get("campaign_id")
        content_items = _load_list(data_dir, _CONTENT_FILENAME)
        items = []
        for record in content_items:
            if record.get("project_id") != project_id:
                continue
            if campaign_id is not None and record.get("campaign_id") != campaign_id:
                continue
            items.append(_public_content(record))
        return {"items": items}

    raise ValueError("unknown operation: %s" % op)

